#include <iostream>
#include <map>
#include <utility>
#include <algorithm>

using namespace std;

long long go(int n, int h, map<pair<int, int>, long long> &v) {
    pair<int, int> key = make_pair(n, h);
    if (v.find(key) == v.end()) {
        if (n == 0) {
            v[key] = 1;
        } else {
            long long sum_val = 0;
            if (h > 0) {
                for (int i = 0; i < n; ++i) {
                    sum_val += go(i, h - 1, v) * go(n - 1 - i, h - 1, v);
                }
            }
            v[key] = sum_val;
        }
    }
    return v[key];
}

int main() {
    int n, h;
    cin >> n >> h;
    map<pair<int, int>, long long> v;
    cout << go(n, n, v) - go(n, max(0, h - 1), v) << endl;
    return 0;
}

